229	static void g_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
230	                   int thickness, uint32_t hex)
231	{
232	    const double a = (double)deg * 3.14159265358979 / 180.0;
233	    const int x1 = cx + (int)lround(sin(a) * r1);
234	    const int y1 = cy - (int)lround(cos(a) * r1);
235	    const int x2 = cx + (int)lround(sin(a) * r2);
236	    const int y2 = cy - (int)lround(cos(a) * r2);
237	
238	    (void)d2_poly(p, g_seg(x1, y1, x2, y2), 2, thickness, hex, true);
239	}
240	
241	static void g_tiller(lv_obj_t *p, int cx, int cy, int deg, int r0, int r1)
242	{
243	    const double a = (double)deg * 3.14159265358979 / 180.0;
244	    const double sx = sin(a);
245	    const double sy = -cos(a);
246	    const double px = cos(a);
247	    const double py = sin(a);
248	    const int x0 = cx + (int)lround(sx * r0);
249	    const int y0 = cy + (int)lround(sy * r0);
250	    const int x1 = cx + (int)lround(sx * r1);
251	    const int y1 = cy + (int)lround(sy * r1);
252	
253	    (void)d2_poly(p, g_seg(x0, y0, x1, y1), 2, 3, G_INK, true);
254	    (void)d2_poly(p, g_seg(x1 - (int)lround(px * 8),
255	                           y1 - (int)lround(py * 8),
256	                           x1 + (int)lround(px * 8),
257	                           y1 + (int)lround(py * 8)),
258	                  2, 3, G_INK, true);
259	}
