295	        }
296	        case G_ICON_RECORD:   /* 三根柱 */
297	            (void)d_box(p, cx - 7, cy - 1, 3, 9, hex, LV_OPA_COVER, 1);
298	            (void)d_box(p, cx - 1, cy - 7, 3, 15, hex, LV_OPA_COVER, 1);
