301	        case G_ICON_SET: {    /* 三条滑杆 + 旋钮 */
302	            for (int i = 0; i < 3; i++) {
303	                (void)d_box(p, cx - 8, cy - 5 + i * 5, 16, 2, hex,
304	                            LV_OPA_COVER, 1);
305	            }
306	            (void)d_box(p, cx + 1, cy - 7, 4, 4, hex, LV_OPA_COVER, 2);
307	            (void)d_box(p, cx - 5, cy - 2, 4, 4, hex, LV_OPA_COVER, 2);
308	            (void)d_box(p, cx + 4, cy + 3, 4, 4, hex, LV_OPA_COVER, 2);
309	            break;
310	        }
311	        case G_ICON_DISPLAY: { /* 显示器 */
312	            lv_obj_t *o = d_box(p, cx - 9, cy - 8, 18, 12, 0x000000u,
313	                                LV_OPA_TRANSP, 2);
