315	            lv_obj_set_style_border_width(o, 2, 0);
316	            lv_obj_set_style_border_color(o, lv_color_hex(hex), 0);
317	            lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
318	            (void)d_box(p, cx - 4, cy + 5, 8, 2, hex, LV_OPA_COVER, 1);
319	            break;
320	        }
321	        case G_ICON_SENSOR: {  /* 心电波形 */
322	            const lv_point_precise_t wave[6] = {
323	                { cx - 9, cy }, { cx - 5, cy }, { cx - 3, cy - 6 },
324	                { cx, cy + 6 }, { cx + 2, cy - 2 }, { cx + 9, cy - 2 },
325	            };
326	
327	            (void)d2_poly(p, g_pts(wave, 6), 6, 2, hex, true);
328	            break;
329	        }
330	        case G_ICON_SOUND: {  /* 喇叭 + 一声波 */
331	            const lv_point_precise_t spk[7] = {
332	                { cx - 7, cy - 2 }, { cx - 4, cy - 2 }, { cx + 1, cy - 6 },
333	                { cx + 1, cy + 6 }, { cx - 4, cy + 2 }, { cx - 7, cy + 2 },
334	                { cx - 7, cy - 2 },
335	            };
336	
337	            (void)d2_poly(p, g_pts(spk, 7), 7, 2, hex, true);
338	            (void)d2_poly(p, g_seg(cx + 4, cy - 3, cx + 6, cy), 2, 2, hex, true);
339	            break;
340	        }
341	        case G_ICON_INFO: {   /* i */
342	            (void)d2_ring(p, cx, cy, 17, 2, hex);
343	            (void)d_box(p, cx - 1, cy - 5, 3, 3, hex, LV_OPA_COVER, 1);
344	            (void)d_box(p, cx - 1, cy - 1, 3, 7, hex, LV_OPA_COVER, 1);
