479	/**
480	 * @brief 盘面：双色轨道 + 选中扇区（浅 20% + 深色轨道边）+ 24 刻度 + 舵柄。
481	 *
482	 * 轨道 = 整圈 26% 黑 + 选中扇区所在弧段的模式深色（2px，压在浅填充外沿），
483	 * 这样"已选区有色、未选区灰"是一条连续的轨道，而不是再加一圈外沿。
484	 *
485	 * @param old_mode 旧模式（half_a 的颜色）
486	 * @param new_mode 新模式（half_b / 轨道象限的颜色）
487	 * @param half_a 旧扇区中心角（-1 = 不画），opa_a 旧扇区透明度
488	 * @param half_b 新扇区中心角（-1 = 不画），opa_b 新扇区透明度
489	 */
490	static void g_dial(lv_obj_t *p, int cx, int cy, int half_a, lv_opa_t opa_a,
491	                   int old_mode, int half_b, lv_opa_t opa_b, int new_mode,
492	                   int ptr_deg, bool progress)
493	{
494	    /* 整圈未选轨道：2px、26% 黑。 */
495	    (void)d2_ring(p, cx, cy, 160, 2, G_TRACK);
496	
497	    /* 扇区填充：d=160 / 24px（LVGL 弧在内侧：r=56..80），正好顶到轨道。 */
498	    if (half_a >= 0) {
499	        const int a = half_a - 90;
500	
501	        (void)g_arc(p, cx, cy, 160, 24, a - 26, 52, g_light[old_mode], false,
502	                    opa_a);
503	    }
504	    if (half_b >= 0) {
505	        const int a = half_b - 90;
506	
507	        (void)g_arc(p, cx, cy, 160, 24, a - 26, 52, g_light[new_mode], false,
508	                    opa_b);
509	    }
510	
511	    /* 已选区轨道 = 模式深色，正好压在浅填充的外沿（r=80）。 */
512	    if (half_a >= 0) {
513	        (void)g_arc(p, cx, cy, 160, 2, half_a - 90 - 26, 52, g_deep[old_mode],
514	                    false, opa_a);
515	    }
516	    if (half_b >= 0) {
517	        (void)g_arc(p, cx, cy, 160, 2, half_b - 90 - 26, 52, g_deep[new_mode],
518	                    false, opa_b);
519	    }
520	
521	    for (int i = 0; i < 24; i++) {
522	        const int deg = i * 15;
523	        const bool major = (i % 6 == 0);
524	
525	        g_tick(p, cx, cy, deg, major ? 66 : 69, 74,
526	               major ? 3 : 1, major ? G_INK : G_TICK);
527	    }
528	
529	    g_tiller(p, cx, cy, ptr_deg, 56, 84);
530	
531	    if (progress) {
532	        lv_obj_t *pr;
533	
534	        /* 长按是模态态：轨道加粗到 4px，270° 进度从 135° 起。 */
535	        (void)d2_ring(p, cx, cy, 160, 4, G_TRACK);
536	        pr = g_arc(p, cx, cy, 160, 4, 135, 270, g_deep[G_RIDE], true,
537	                   LV_OPA_COVER);
538	        lv_arc_set_value(pr, 50);
539	    }
540	}
