601	
602	static void g_main_common(int screen)
603	{
604	    const bool rotate = (screen == G_SCR_ROTATE);
605	    const bool press = (screen == G_SCR_LONGPRESS);
606	    const int on = rotate ? 1 : 0;
607	    const int ptr = rotate ? 45 : 0;
608	    const int sector = press ? -1 : on * 90;
609	    const g_mode_t *m = &g_modes[on];
610	
611	    d_bg(s_scr, G_BG);
612	    g_top(s_scr, "模式", rotate ? "01 → 02" : "01 / 04");
