675	/** 速度区间带：0-30 / 30-45 / 45-60 三段冷→暖，游标 3×20。 */
676	static void g_speed_band(lv_obj_t *p, int y, double speed)
677	{
678	    const int x0 = 52;
679	    const int w = 164;
680	    const int w1 = 82;
681	    const int w2 = 41;
682	
683	    g_lab(p, "速度", G_PX_MICRO, G_MUTE, 24, y + 2);
684	
685	    (void)d_box(p, x0, y, w1, 18, g_light[G_NAV], LV_OPA_COVER, 0);
686	    (void)d_box(p, x0 + w1, y, w2, 18, g_light[G_RIDE], LV_OPA_COVER, 0);
687	    (void)d_box(p, x0 + w1 + w2, y, w2, 18, g_light[G_RECORD], LV_OPA_COVER, 0);
688	
689	    /* 2px 深色顶沿：浅填充在阳光档会掉色，这三条深色轨道不会。 */
690	    (void)d_box(p, x0, y, w1, 2, g_deep[G_NAV], LV_OPA_COVER, 0);
691	    (void)d_box(p, x0 + w1, y, w2, 2, g_deep[G_RIDE], LV_OPA_COVER, 0);
692	    (void)d_box(p, x0 + w1 + w2, y, w2, 2, g_deep[G_RECORD], LV_OPA_COVER, 0);
693	
694	    /* 段边界 1px 近黑，保证三段在阳光档下还有分界。 */
695	    (void)d_box(p, x0 + w1, y, 1, 18, G_INK, LV_OPA_COVER, 0);
696	    (void)d_box(p, x0 + w1 + w2, y, 1, 18, G_INK, LV_OPA_COVER, 0);
697	
698	    g_lab(p, "0", G_PX_MICRO, G_INK, x0 + 4, y + 3);
699	    g_lab(p, "30", G_PX_MICRO, G_INK, x0 + w1 + 3, y + 3);
700	    g_lab(p, "60", G_PX_MICRO, G_INK, x0 + w - 16, y + 3);
701	
702	    {
703	        int x = x0 + (int)lround(w * speed / 60.0);
704	
705	        if (x < x0 + 1) {
706	            x = x0 + 1;
707	        }
708	        if (x > x0 + w - 4) {
709	            x = x0 + w - 4;
710	        }
711	        (void)d_box(p, x, y - 2, 3, 22, G_INK, LV_OPA_COVER, 1);
712	    }
713	}
