1460	static void g_build(lv_obj_t *scr, int screen)
1461	{
1462	    switch (screen) {
1463	        case G_SCR_ROTATE:      g_rotate(scr); break;
1464	        case G_SCR_LONGPRESS:   g_longpress(scr); break;
1465	        case G_SCR_RIDE:        g_ride(scr); break;
1466	        case G_SCR_NAV:         g_nav(scr); break;
1467	        case G_SCR_RECORD:      g_record(scr); break;
1468	        case G_SCR_SETTINGS:    g_settings(scr); break;
1469	        case G_SCR_DISPLAY:     g_display(scr); break;
1470	        case G_SCR_SENSOR:      g_sensor(scr); break;
1471	        case G_SCR_ABOUT:       g_about(scr); break;
1472	        case G_SCR_ANIM_ROTATE: g_anim_rotate(scr); break;
1473	        case G_SCR_ANIM_ENTER:  g_anim_enter(scr); break;
1474	        case G_SCR_ANIM_BACK:   g_anim_back(scr); break;
1475	        default:                g_main(scr); break;
1476	    }
1477	}
