1479	static int g_count_objs(lv_obj_t *o)
1480	{
1481	    int n = 1;
1482	    const uint32_t c = lv_obj_get_child_count(o);
1483	
1484	    for (uint32_t i = 0; i < c; i++) {
1485	        n += g_count_objs(lv_obj_get_child(o, (int32_t)i));
1486	    }
1487	    return n;
1488	}
1489	
1490	static void g_rebuild(int screen)
1491	{
1492	    if (screen < 0 || screen >= G_SCR_COUNT) {
1493	        screen = G_SCR_MAIN;
1494	    }
1495	#ifdef SIM_WITH_UI
1496	    g_vmap_stop();
1497	#endif
1498	    lv_obj_clean(s_scr);
1499	    g_pts_reset();

1500	    memset(s_font_use, 0, sizeof(s_font_use));
1501	    g_build(s_scr, screen);
1502	    printf("design4: screen=%s objects=%d fonts", g_screen_names[screen],
1503	           g_count_objs(s_scr));
1504	    for (int i = 0; i < 128; i++) {
1505	        if (s_font_use[i] != 0) {
1506	            printf(" %d=%d", i, s_font_use[i]);
1507	        }
1508	    }
1509	    printf("\n");
1510	    fflush(stdout);
1511	}
