1513	static int g_screen_from_env(void)
1514	{
1515	    const char *s = getenv("SIM_DESIGN_SCREEN");
1516	
1517	    if (s == NULL || s[0] == '\0') {
1518	        return G_SCR_MAIN;
1519	    }
1520	    for (int i = 0; i < G_SCR_COUNT; i++) {
1521	        if (strcmp(s, g_screen_names[i]) == 0) {
1522	            return i;
1523	        }
1524	    }
1525	    if (strcmp(s, "menu") == 0) {
1526	        return G_SCR_SETTINGS;
1527	    }
1528	    if (s[0] >= '0' && s[0] <= '9' && s[1] == '\0') {
1529	        return s[0] - '0';
1530	    }
1531	    fprintf(stderr,
1532	            "sim: unknown SIM_DESIGN_SCREEN=%s "
1533	            "(main|rotate|longpress|ride|nav|record|settings|display|sensor|"
1534	            "about|anim_dial_rotate|anim_enter_ride|anim_back)\n", s);
1535	    return G_SCR_MAIN;
1536	}
