1538	static void g_key_timer(lv_timer_t *t)
1539	{
1540	    (void)t;
1541	    for (;;) {
1542	        int k = sim_display_take_raw_key();
1543	
1544	        if (k == 0) {
1545	            break;
1546	        }
1547	        if (k >= '1' && k <= '9') {
1548	            g_rebuild(k - '1');
1549	        } else if (k == '0') {
1550	            g_rebuild(G_SCR_ABOUT);
1551	        }
1552	    }
1553	}
