61	static inline uint32_t rgb565_to_xrgb(uint16_t c)
62	{
63	    uint32_t r = (uint32_t)((c >> 11) & 0x1Fu);
64	    uint32_t g = (uint32_t)((c >> 5) & 0x3Fu);
65	    uint32_t b = (uint32_t)(c & 0x1Fu);
66	
67	    r = (r << 3) | (r >> 2);
68	    g = (g << 2) | (g >> 4);
69	    b = (b << 3) | (b >> 2);
70	    return (r << 16) | (g << 8) | b;
71	}
