73	/* 把影子缓冲的一块画到窗口（只画脏矩形，缩放用最近邻）。 */
74	static void blit_rect(int x0, int y0, int w, int h)
75	{
76	    if (s.headless || !s.dpy || !s.img) {
77	        return;
78	    }
79	
80	    const int sc = s.scale;
81	    const int iw = s.w * sc;
82	    const bool fast = (s.img->bits_per_pixel == 32);
83	
84	    for (int y = 0; y < h; y++) {
85	        const uint16_t *src = s.shadow + (size_t)(y0 + y) * (size_t)s.w + x0;
86	        for (int sy = 0; sy < sc; sy++) {
87	            int row = (y0 + y) * sc + sy;
88	            for (int x = 0; x < w; x++) {
89	                uint32_t rgb = rgb565_to_xrgb(src[x]);
90	                for (int sx = 0; sx < sc; sx++) {
91	                    int col = (x0 + x) * sc + sx;
92	                    if (fast) {
93	                        ((uint32_t *)s.img->data)[(size_t)row * (size_t)iw + col] = rgb;
94	                    } else {
95	                        XPutPixel(s.img, col, row, rgb);
96	                    }
97	                }
98	            }
99	        }
100	    }
101	    XPutImage(s.dpy, s.win, s.gc, s.img, x0 * sc, y0 * sc, x0 * sc, y0 * sc,
102	              (unsigned)w * (unsigned)sc, (unsigned)h * (unsigned)sc);
103	    XFlush(s.dpy);
104	}
