187	static uint32_t xkey_to_lv(KeySym ks)
188	{
189	    switch (ks) {
190	        case XK_Left:  return LV_KEY_LEFT;
191	        case XK_Right: return LV_KEY_RIGHT;
192	        case XK_Up:    return LV_KEY_UP;
193	        case XK_Down:  return LV_KEY_DOWN;
194	        case XK_Return:
195	        case XK_KP_Enter: return LV_KEY_ENTER;
196	        case XK_Escape:   return LV_KEY_ESC;
197	        case XK_BackSpace:return LV_KEY_BACKSPACE;
198	        case XK_Tab:      return LV_KEY_NEXT;
199	        case XK_Home:     return LV_KEY_HOME;
200	        case XK_End:      return LV_KEY_END;
201	        default: return 0;
202	    }
203	}
