214	/* ── 事件循环 ──────────────────────────────────────────────────── */
215	
216	bool sim_display_pump(void)
217	{
218	    if (s.headless || !s.dpy) {
219	        return !s.quit;
220	    }
221	
222	    while (XPending(s.dpy)) {
223	        XEvent ev;
224	
225	        XNextEvent(s.dpy, &ev);
226	        switch (ev.type) {
227	            case Expose:
228	                if (ev.xexpose.count == 0) {
229	                    blit_rect(0, 0, s.w, s.h);
230	                }
231	                break;
232	            case MotionNotify:
233	                s.mx = ev.xmotion.x / s.scale;
234	                s.my = ev.xmotion.y / s.scale;
235	                if (s.mx < 0) s.mx = 0;
236	                if (s.my < 0) s.my = 0;
237	                if (s.mx > s.w - 1) s.mx = s.w - 1;
238	                if (s.my > s.h - 1) s.my = s.h - 1;
239	                break;
240	            case ButtonPress:
241	                if (ev.xbutton.button == Button1) {
242	                    s.pressed = true;
243	                } else if (ev.xbutton.button == Button4) {
244	                    s.wheel++;      /* 滚轮上 = 放大 */
245	                } else if (ev.xbutton.button == Button5) {
246	                    s.wheel--;      /* 滚轮下 = 缩小 */
247	                }
248	                break;
249	            case ButtonRelease:
250	                if (ev.xbutton.button == Button1) {
251	                    s.pressed = false;
252	                }
253	                break;
254	            case KeyPress: {
255	                KeySym ks = XLookupKeysym(&ev.xkey, 0);
256	                uint32_t key = xkey_to_lv(ks);
257	
258	                if (key) {
259	                    key_push(key);
260	                }
261	                /* `vmap` 场景的快捷键（其它场景不轮询，等于不存在）。 */
262	                switch (ks) {
263	                    case XK_1: raw_key_push('1'); break;
264	                    case XK_2: raw_key_push('2'); break;
265	                    case XK_3: raw_key_push('3'); break;
266	                    case XK_r: raw_key_push('r'); break;
267	                    case XK_f: raw_key_push('f'); break;
268	                    case XK_i: raw_key_push('i'); break;
269	                    case XK_c: raw_key_push('c'); break;
270	                    case XK_plus: case XK_equal: case XK_KP_Add:
271	                        raw_key_push('+');
272	                        break;
273	                    case XK_minus: case XK_KP_Subtract:
274	                        raw_key_push('-');
275	                        break;
276	                    default:
277	                        break;
278	                }
279	                break;
280	            }
281	            case ClientMessage:
282	                if ((Atom)ev.xclient.data.l[0] == s.wm_delete) {
283	                    s.quit = true;
284	                }
285	                break;
286	            case DestroyNotify:
287	                s.quit = true;
288	                break;
289	            default:
290	                break;
291	        }
292	    }
293	    return !s.quit;
294	}
