297	
298	static bool shadow_alloc(void)
299	{
300	    s.shadow = calloc((size_t)s.w * (size_t)s.h, sizeof(uint16_t));
301	    if (!s.shadow) {
302	        fprintf(stderr, "sim: out of memory for shadow framebuffer\n");
303	        return false;
304	    }
305	    for (size_t i = 0; i < (size_t)s.w * (size_t)s.h; i++) {
306	        s.shadow[i] = 0xFFFF;
307	    }
308	    return true;
309	}
310	
311	static bool window_open(const sim_cfg_t *cfg)
312	{
313	    const int scr = DefaultScreen(s.dpy);
314	    const int win_w = s.w * s.scale;
315	    const int win_h = s.h * s.scale;
316	
317	    s.win = XCreateSimpleWindow(s.dpy, RootWindow(s.dpy, scr), 0, 0,
318	                                (unsigned)win_w, (unsigned)win_h, 0,
319	                                BlackPixel(s.dpy, scr), WhitePixel(s.dpy, scr));
320	    XStoreName(s.dpy, s.win, cfg->title ? cfg->title : "lvgl_sim");
321	
322	    XSizeHints hints;
323	    memset(&hints, 0, sizeof(hints));
324	    hints.flags = PMinSize | PMaxSize;
325	    hints.min_width = hints.max_width = win_w;
326	    hints.min_height = hints.max_height = win_h;
327	    XSetWMNormalHints(s.dpy, s.win, &hints);
328	
329	    s.wm_delete = XInternAtom(s.dpy, "WM_DELETE_WINDOW", False);
330	    XSetWMProtocols(s.dpy, s.win, &s.wm_delete, 1);
331	
332	    XSelectInput(s.dpy, s.win,
333	                 ExposureMask | ButtonPressMask | ButtonReleaseMask |
334	                 PointerMotionMask | KeyPressMask | StructureNotifyMask);
335	
336	    s.gc = XCreateGC(s.dpy, s.win, 0, NULL);
337	
338	    s.img = XCreateImage(s.dpy, DefaultVisual(s.dpy, scr),
339	                         (unsigned)DefaultDepth(s.dpy, scr), ZPixmap, 0, NULL,
340	                         (unsigned)win_w, (unsigned)win_h, 32, 0);
341	    if (!s.img) {
342	        fprintf(stderr, "sim: XCreateImage failed\n");
343	        return false;
344	    }
345	    s.img->data = calloc((size_t)s.img->bytes_per_line, (size_t)win_h);
346	    if (!s.img->data) {
347	        fprintf(stderr, "sim: out of memory for XImage\n");
348	        return false;
349	    }
350	
351	    XMapWindow(s.dpy, s.win);
352	    XFlush(s.dpy);
353	
354	    if (s.img->bits_per_pixel != 32) {
355	        fprintf(stderr, "sim: warning: X server is %d bpp, using slow XPutPixel path\n",
356	                s.img->bits_per_pixel);
357	    }
358	    return true;
359	}
