361	bool sim_display_init(const sim_cfg_t *cfg)
362	{
363	    s.w = cfg->width > 0 ? cfg->width : 240;
364	    s.h = cfg->height > 0 ? cfg->height : 400;
365	    s.scale = cfg->scale > 0 ? cfg->scale : 2;
366	    s.headless = cfg->headless;
367	    s.quit = false;
368	
369	    if (!shadow_alloc()) {
370	        return false;
371	    }
372	    if (s.headless) {
373	        return true;
374	    }
375	
376	    s.dpy = XOpenDisplay(NULL);
377	    if (!s.dpy) {
378	        fprintf(stderr, "sim: cannot open X display; use --headless --shot out.png\n");
379	        return false;
380	    }
381	    return window_open(cfg);
382	}
