384	void sim_lvgl_bind(void)
385	{
386	    /* 两个 1/10 屏的局部缓冲：和设备的渲染模式一致，刷新时只送脏矩形 */
387	    const uint32_t stride = (uint32_t)s.w;
388	    const uint32_t lines = 40;
389	    const uint32_t bytes = stride * lines * 2u;
390	    void *buf1 = lv_malloc(bytes);
391	    void *buf2 = lv_malloc(bytes);
392	
393	    lv_display_t *disp = lv_display_create(s.w, s.h);
394	
395	    lv_display_set_flush_cb(disp, flush_cb);
396	    lv_display_set_buffers(disp, buf1, buf2, bytes, LV_DISPLAY_RENDER_MODE_PARTIAL);
397	    lv_display_set_default(disp);
398	
399	    s.indev_ptr = lv_indev_create();
400	    lv_indev_set_type(s.indev_ptr, LV_INDEV_TYPE_POINTER);
401	    lv_indev_set_read_cb(s.indev_ptr, pointer_read);
402	
403	    s.indev_key = lv_indev_create();
404	    lv_indev_set_type(s.indev_key, LV_INDEV_TYPE_KEYPAD);
405	    lv_indev_set_read_cb(s.indev_key, keypad_read);
406	    lv_indev_set_group(s.indev_key, sim_input_group());
407	}
408	
409	const uint16_t *sim_display_shadow(int *w, int *h)
410	{
411	    if (w) *w = s.w;
412	    if (h) *h = s.h;
413	    return s.shadow;
414	}
415	
416	void sim_display_shutdown(void)
417	{
418	    if (s.img) {
419	        /* XDestroyImage 会 free(data) */
420	        XDestroyImage(s.img);
421	        s.img = NULL;
422	    }
423	    if (s.gc && s.dpy) {
424	        XFreeGC(s.dpy, s.gc);
425	        s.gc = NULL;
426	    }
427	    if (s.win && s.dpy) {
428	        XDestroyWindow(s.dpy, s.win);
429	        s.win = 0;
430	    }
431	    if (s.dpy) {
432	        XCloseDisplay(s.dpy);
433	        s.dpy = NULL;
434	    }
435	    free(s.shadow);
436	    s.shadow = NULL;
437	}
