### dial_rotate_start
```c
static lv_anim_t *s_rot_anim;
static int s_rot_from_angle, s_rot_to_angle, s_rot_from_mode, s_rot_to_mode;
static lv_opa_t s_rot_opa_a0, s_rot_opa_b0;
static bool s_rot_label_swapped;
static int32_t s_rot_p;   /* 0..1000 */

static void rot_exec(void *var, int32_t p) {
  int ang = s_rot_from_angle + (s_rot_to_angle - s_rot_from_angle) * p / 1000;
  D.angle = ang;
  dial_layout_pointer(ang);
  lv_opa_t oa = s_rot_opa_a0 * (1000-p)/1000;
  lv_opa_t ob = s_rot_opa_b0 + (255 - s_rot_opa_b0) * p/1000;
  if (D.fill) { set arc opa oa }...
  if (D.fill2) { set arc opa ob }
  if (!s_rot_label_swapped && p >= 500) { s_rot_label_swapped=true; dial_set_content(s_rot_to_mode); }
}
```
Note: lv_obj_set_style_arc_opa on the fill affects only the indicator (main arc is transparent). Good. For trk arcs, also indicator.

`rot_ready`: delete A; A=B; B=NULL; set A opa 100; D.mode = to; D.angle = to_angle; dial_layout_pointer; dial_set_content(to); top_r final; s_rot_anim=NULL.

Interrupt:
```c
static void dial_rotate_next(void) {
  int from_mode, to_mode;
  lv_opa_t a0, b0;
  if (s_rot_anim) {
