     s_rot_anim = NULL;
     /* B 升为 A */
     lv_obj_delete(D.fill); lv_obj_delete(D.trk);
     D.fill = D.fill2; D.trk = D.trk2; D.fill2 = D.trk2 = NULL;
     from_mode = s_rot_to_mode;
     a0 = s_rot_opa_b_current; // updated in exec
     b0 = 0;
     D.mode = from_mode;  // committed for bookkeeping? The display may not be switched yet.
     s_rot_label_swapped = true? 
  } else {
     from_mode = D.mode;
     a0 = 255; b0 = 0;
  }
  to_mode = (from_mode+1)%4;
  s_rot_from_angle = D.angle;
  int target = 90*to_mode; while (target <= D.angle) target += 360;
  s_rot_to_angle = target;
  s_rot_from_mode = from_mode; s_rot_to_mode = to_mode;
  s_rot_opa_a0 = a0; s_rot_opa_b0 = b0;
