/* ── 数据 ──────────────────────────────────────────────────────── */

static double week_total(void)
{
    double sum = 0.0;

    for (int i = 0; i < 7; i++) {
        sum += (double)s_week[i];
    }
    return sum;
}

static int week_rides(void)
{
    int n = 0;

    for (int i = 0; i < 7; i++) {
        if (s_week[i] != 0) {
            n++;
        }
    }
    return n;
}

static int hr_zone(int bpm)
{
    if (bpm < 118) return 1;
    if (bpm < 132) return 2;
    if (bpm < 145) return 3;
    if (bpm < 160) return 4;
    return 5;
}

static void ride_step(void)
{
    R.seed = R.seed * 1103515245u + 12345u;
    R.t += 1.0;
    {
        const double n = (double)((R.seed >> 16) & 0x7FFF) / 32767.0 - 0.5;
        double sp = 22.5 + 5.5 * sin(R.t / 8.0) + 1.6 * n;

        if (sp < 8.0) sp = 8.0;
        if (sp > 45.0) sp = 45.0;
        R.speed = sp;
        R.dist_km += sp / 3600.0;
        R.hr = 126 + (int)(sp * 1.05) + (int)(3.0 * n);
        R.cadence = 78 + (int)(sp * 0.5) + (int)(4.0 * n);
        R.elevation = 326 + (int)(9.0 * sin(R.t / 21.0));
        if (n > 0.28) {
            R.ascent += 1;
        }
        R.cal = (int)(R.dist_km * 32.0);
        if (R.speed > R.max) {
            R.max = R.speed;
        }
        R.avg = (R.elapsed_s > 0)
                    ? R.dist_km / ((double)R.elapsed_s / 3600.0)
                    : R.speed;
    }
    {
        const double s = R.speed;
        const int bin = (s < 15.0) ? 0 : (s < 25.0) ? 1 : (s < 35.0) ? 2
                      : (s < 45.0) ? 3 : 4;

        R.hist[bin]++;
    }
}

static void rec_init(void)
{
    static const rec_t init[4] = {
        { "10/28 周三", "1:42 · 24.8", 42.6, { 3, 8, 20, 12, 6 } },
        { "10/26 周一", "0:58 · 22.1", 21.4, { 4, 10, 18, 8, 5 } },
        { "10/24 周六", "2:16 · 26.3", 59.7, { 2, 6, 16, 18, 9 } },
        { "10/21 周三", "0:44 · 20.6", 15.1, { 5, 11, 14, 7, 4 } },
    };
    static const int week[7] = { 0, 21, 0, 0, 42, 0, 5 };

    memcpy(s_recs, init, sizeof(init));
    s_rec_n = 4;
    memcpy(s_week, week, sizeof(week));
}

static void ride_start(void)
{
    memset(&R, 0, sizeof(R));
    R.active = true;
    R.seed = 0x2468ACEu;
    R.speed = 0.0;
    R.hr = 126;
    R.cadence = 78;
    R.elevation = 326;
    ride_step();
    ride_step();
}

static void ride_finish(void)
{
    char date[16];
    char sub[24];
    rec_t r;
    int hmax = 1;

    if (!R.active) {
        return;
    }
    R.active = false;

    snprintf(date, sizeof(date), "10/29 周四");
    snprintf(sub, sizeof(sub), "%u:%02u · %.1f",
             (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60),
             R.avg);
    memset(&r, 0, sizeof(r));
    snprintf(r.date, sizeof(r.date), "%s", date);
    snprintf(r.sub, sizeof(r.sub), "%s", sub);
    r.dist = R.dist_km > 0.1 ? R.dist_km : 0.1;
    for (int i = 0; i < 5; i++) {
        if (R.hist[i] > hmax) {
            hmax = R.hist[i];
        }
    }
    for (int i = 0; i < 5; i++) {
        r.bars[i] = 10 + (R.hist[i] * 28) / hmax;
        if (r.bars[i] < 10) r.bars[i] = 10;
    }
    if (s_rec_n < (int)(sizeof(s_recs) / sizeof(s_recs[0]))) {
        s_rec_n++;
    }
    memmove(&s_recs[1], &s_recs[0],
            (size_t)(s_rec_n - 1) * sizeof(s_recs[0]));
    s_recs[0] = r;
    s_week[6] += (int)(r.dist + 0.5);

    {
        char msg[64];

        snprintf(msg, sizeof(msg), "已保存 · %.1f km · %u:%02u", r.dist,
                 (unsigned)(R.elapsed_s / 60), (unsigned)(R.elapsed_s % 60));
        toast(msg);
    }
}

static void toggle_ride(void)
{
    if (R.active) {
        ride_finish();
        if (s_screen != SCR_DIAL) {
            s_screen = SCR_DIAL;
            s_busy = false;
            /* rebuild 由调用方在事件处理完后执行 */
        }
    } else {
        ride_start();
        s_screen = SCR_RIDE;
        s_busy = false;
    }
}

