/* ── 盘面旋转（ANIMATION #1/#2）────────────────────────────────── */

static lv_anim_t *s_rot_anim;
static int32_t s_rot_p;
static int s_rot_a0, s_rot_a1;
static int s_rot_oa0, s_rot_ob0;
static int s_rot_from_mode, s_rot_to_mode;
static bool s_rot_swapped;

static void rot_exec(void *var, int32_t p)
{
    (void)var;
    s_angle = s_rot_a0 + (s_rot_a1 - s_rot_a0) * (int)p / 1000;
    UD.angle = s_angle;
    dial_pointer_layout(s_angle);
    SET_ARC_OPA(UD.fill, s_rot_oa0 * (1000 - (int)p) / 1000);
    SET_ARC_OPA(UD.trk, s_rot_oa0 * (1000 - (int)p) / 1000);
    SET_ARC_OPA(UD.fill2, s_rot_ob0 + (255 - s_rot_ob0) * (int)p / 1000);
    SET_ARC_OPA(UD.trk2, s_rot_ob0 + (255 - s_rot_ob0) * (int)p / 1000);
    if (!s_rot_swapped && p >= 500) {
        s_rot_swapped = true;
        dial_content(s_rot_to_mode);
    }
}

static void rot_ready(lv_anim_t *a)
{
    (void)a;
    s_rot_anim = NULL;
    if (UD.fill != NULL) {
        lv_obj_delete(UD.fill);
        lv_obj_delete(UD.trk);
    }
    UD.fill = UD.fill2;
    UD.trk = UD.trk2;
    UD.fill2 = NULL;
    UD.trk2 = NULL;
    SET_ARC_OPA(UD.fill, 255);
    SET_ARC_OPA(UD.trk, 255);
    s_mode = s_rot_to_mode;
    s_angle = s_rot_a1;
    UD.angle = s_angle;
    dial_pointer_layout(s_angle);
    dial_content(s_mode);
    {
        char buf[24];

        snprintf(buf, sizeof(buf), "%02d / 04", s_mode + 1);
        lv_label_set_text(UD.top_r, buf);
    }
    s_busy = false;
}

static void dial_rotate_next(void)
{
    int from_mode;
    int to_mode;
    int a0;
    int target;
    lv_anim_t a;

    if (UD.fill == NULL || s_busy) {
        return;
    }
    from_mode = s_rot_to_mode;
    a0 = (int)s_angle;

    if (s_rot_anim != NULL) {
        /* ANIMATION #2：从当前角重定目标，120ms；旧 B 升为 A。 */
        lv_anim_delete(&s_rot_p, NULL);
        s_rot_anim = NULL;
        if (UD.fill != NULL) {
            lv_obj_delete(UD.fill);
            lv_obj_delete(UD.trk);
        }
        UD.fill = UD.fill2;
        UD.trk = UD.trk2;
        UD.fill2 = NULL;
        UD.trk2 = NULL;
        s_rot_oa0 = 128;
        s_rot_ob0 = 128;
        s_mode = from_mode;
    } else {
        from_mode = s_mode;
        s_rot_oa0 = 255;
        s_rot_ob0 = 0;
    }
    to_mode = (from_mode + 1) % M_COUNT;

    target = to_mode * 90;
    while (target <= a0) {
        target += 360;
    }

    s_rot_a0 = a0;
    s_rot_a1 = target;
    s_rot_from_mode = from_mode;
    s_rot_to_mode = to_mode;
    s_rot_swapped = false;
    dial_sector(to_mode, (lv_opa_t)s_rot_ob0, &UD.fill2, &UD.trk2);
    {
        char buf[24];

        snprintf(buf, sizeof(buf), "%02d → %02d", s_shown_mode + 1,
                 to_mode + 1);
        lv_label_set_text(UD.top_r, buf);
    }

    s_busy = true;
    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_rot_p);
    lv_anim_set_values(&a, 0, 1000);
    lv_anim_set_duration(&a, s_rot_anim == NULL && a0 % 90 != 0 ? 120 : 160);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
    lv_anim_set_exec_cb(&a, rot_exec);
    lv_anim_set_ready_cb(&a, rot_ready);
    s_rot_anim = lv_anim_start(&a);
}

