static void rec_week_bars(void)
{
    int mx = 1;

    for (int i = 0; i < 7; i++) {
        if (s_week[i] > mx) mx = s_week[i];
    }
    for (int i = 0; i < 7; i++) {
        int h = s_week[i] == 0 ? 2 : (s_week[i] * 26) / mx;

        if (h < 2) h = 2;
        lv_obj_set_height(UC.week[i], h);
        lv_obj_set_y(UC.week[i], 88 - h);
        lv_obj_set_style_bg_color(UC.week[i],
                                  lv_color_hex(s_week[i] == 0 ? P_TRACK
                                                              : C_DEEP[M_RECORD]),
                                  0);
    }
}

static void rec_rows(void)
{
    int n = s_rec_n < 4 ? s_rec_n : 4;

    for (int i = 0; i < 4; i++) {
        if (i < n) {
            char buf[24];

            lv_label_set_text(UC.date[i], s_recs[i].date);
            lv_label_set_text(UC.sub[i], s_recs[i].sub);
            snprintf(buf, sizeof(buf), "%.1f", s_recs[i].dist);
            lv_label_set_text(UC.dist[i], buf);
            lv_obj_set_style_text_color(UC.date[i],
                                        lv_color_hex(i == s_rec_sel ? P_INK
                                                                    : P_MUTE),
                                        0);
        } else {
            lv_label_set_text(UC.date[i], "—");
            lv_label_set_text(UC.sub[i], "");
            lv_label_set_text(UC.dist[i], "");
        }
    }
}

