    L(s_scr, old ? "线宽/端点/光学尺寸都不一致" : "线宽/端点/光学尺寸由字体统一",
      PX_MICRO, P_MUTE, 16, 300);
}

/* 旧图标（WP-DESIGN4 的几何占位）原样搬来做对照；只在这个屏幕用。 */
void helm_demo_icon(lv_obj_t *p, int kind, int cx, int cy, uint32_t hex)
{
    switch (kind) {
        case 0: { /* 半圆表盘 + 指针 */
            (void)ARC(p, cx, cy + 1, 20, 2, 135, 270, hex, false,
                      LV_OPA_COVER);
            {
                lv_point_precise_t s[2] = { { cx, cy + 1 }, { cx - 6, cy - 4 } };

                (void)LINE(p, s, 2, 2, hex);
            }
            (void)B(p, cx - 1, cy, 3, 3, hex, LV_OPA_COVER, 1);
            break;
        }
        case 1: { /* 右转箭头 */
            lv_point_precise_t a[2] = { { cx - 4, cy + 7 }, { cx - 4, cy - 2 } };
            lv_point_precise_t b[2] = { { cx - 4, cy - 2 }, { cx + 4, cy - 2 } };
            lv_point_precise_t c[2] = { { cx + 1, cy - 7 }, { cx + 5, cy - 2 } };
            lv_point_precise_t d[2] = { { cx + 1, cy + 3 }, { cx + 5, cy - 2 } };

            (void)LINE(p, a, 2, 2, hex);
            (void)LINE(p, b, 2, 2, hex);
            (void)LINE(p, c, 2, 2, hex);
            (void)LINE(p, d, 2, 2, hex);
            break;
        }
        case 2: /* 三根柱 */
            (void)B(p, cx - 7, cy - 1, 3, 9, hex, LV_OPA_COVER, 1);
            (void)B(p, cx - 1, cy - 7, 3, 15, hex, LV_OPA_COVER, 1);
            (void)B(p, cx + 5, cy - 4, 3, 12, hex, LV_OPA_COVER, 1);
            break;
        case 3: /* 三条滑杆 */
            for (int i = 0; i < 3; i++) {
                (void)B(p, cx - 8, cy - 5 + i * 5, 16, 2, hex, LV_OPA_COVER, 1);
            }
            (void)B(p, cx + 1, cy - 7, 4, 4, hex, LV_OPA_COVER, 2);
            (void)B(p, cx - 5, cy - 2, 4, 4, hex, LV_OPA_COVER, 2);
            (void)B(p, cx + 4, cy + 3, 4, 4, hex, LV_OPA_COVER, 2);
            break;
        case 4: { /* 显示器 */
            lv_obj_t *o = B(p, cx - 9, cy - 8, 18, 12, 0x000000u,
                            LV_OPA_TRANSP, 2);

            lv_obj_set_style_border_width(o, 2, 0);
            lv_obj_set_style_border_color(o, lv_color_hex(hex), 0);
            lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
            (void)B(p, cx - 4, cy + 5, 8, 2, hex, LV_OPA_COVER, 1);
            break;
        }
        case 5: { /* 心电波形 */
            lv_point_precise_t w[6] = {
                { cx - 9, cy }, { cx - 5, cy }, { cx - 3, cy - 6 },
                { cx, cy + 6 }, { cx + 2, cy - 2 }, { cx + 9, cy - 2 },
            };

            (void)LINE(p, w, 6, 2, hex);
            break;
        }
        case 6: { /* 喇叭 */
            lv_point_precise_t sp[7] = {
                { cx - 7, cy - 2 }, { cx - 4, cy - 2 }, { cx + 1, cy - 6 },
                { cx + 1, cy + 6 }, { cx - 4, cy + 2 }, { cx - 7, cy + 2 },
                { cx - 7, cy - 2 },
            };
            lv_point_precise_t q[2] = { { cx + 4, cy - 3 }, { cx + 6, cy } };

            (void)LINE(p, sp, 7, 2, hex);
            (void)LINE(p, q, 2, 2, hex);
            break;
        }
        case 7: /* i */
            (void)RING(p, cx, cy, 17, 2, hex);
            (void)B(p, cx - 1, cy - 5, 3, 3, hex, LV_OPA_COVER, 1);
            (void)B(p, cx - 1, cy - 1, 3, 7, hex, LV_OPA_COVER, 1);
            break;
        case 8: { /* GPS 信号格（旧） */
            static const int h[4] = { 4, 7, 10, 13 };

            for (int i = 0; i < 4; i++) {
                (void)B(p, cx - 7 + i * 4, cy + 6 - h[i], 3, h[i], hex,
                        LV_OPA_COVER, 1);
            }
            break;
        }
        case 9: { /* 电池（旧） */
            lv_obj_t *o = B(p, cx - 9, cy - 4, 18, 9, 0x000000u,
                            LV_OPA_TRANSP, 2);

            lv_obj_set_style_border_width(o, 1, 0);
            lv_obj_set_style_border_color(o, lv_color_hex(P_INK), 0);
            lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
            (void)B(p, cx + 9, cy - 2, 2, 5, P_INK, LV_OPA_COVER, 1);
            (void)B(p, cx - 7, cy - 2, 12, 5, hex, LV_OPA_COVER, 1);
            break;
        }
        case 10: { /* 时钟（旧） */
            lv_point_precise_t h1[2] = { { cx, cy }, { cx, cy - 4 } };
            lv_point_precise_t h2[2] = { { cx, cy }, { cx + 3, cy + 1 } };

            (void)RING(p, cx, cy, 14, 2, hex);
            (void)LINE(p, h1, 2, 1, hex);
            (void)LINE(p, h2, 2, 1, hex);
            break;
        }
        default:
            break;
    }
}

/* ── 长按 / 输入 ──────────────────────────────────────────────── */

typedef enum {
    LP_NONE = 0,
    LP_ENTER,      /* 盘面：进入选中模式 */
    LP_ACTIVATE,   /* 设置：进入子页 / 开关声音 */
    LP_ADJUST,     /* 显示：调节焦点项 */
    LP_SEARCH,     /* 传感器：重搜焦点项 */
    LP_TOGGLE_RIDE /* KEY2：开始/结束 */
} lp_target_t;

static struct {
    bool active;
    int key;
    uint32_t t0;
    int pct;
    lp_target_t target;
    lv_obj_t *bar;
    lv_obj_t *track;
    lv_obj_t *arc;
} LP;

static lv_timer_t *s_ui_timer;
static lv_timer_t *s_data_timer;

static bool screen_has_lp1(void)
{
    return s_screen == SCR_DIAL || s_screen == SCR_SETTINGS ||
           s_screen == SCR_DISPLAY || s_screen == SCR_SENSOR;
}

static bool screen_has_lp2(void)
{
    return s_screen == SCR_DIAL || s_screen == SCR_RIDE ||
           s_screen == SCR_NAV || s_screen == SCR_RECORD ||
           s_screen == SCR_SETTINGS;
}

static void lp_ui_clear(void)
{
    if (LP.bar != NULL) {
        lv_obj_delete(LP.bar);
        LP.bar = NULL;
    }
    if (LP.track != NULL) {
        lv_obj_delete(LP.track);
        LP.track = NULL;
    }
    if (LP.arc != NULL) {
        lv_obj_delete(LP.arc);
        LP.arc = NULL;
    }
}

static void lp_sync_text(void)
{
    char buf[96];
    const char *verb = (LP.target == LP_TOGGLE_RIDE)
                           ? (R.active ? "结束骑行" : "开始骑行")
                           : "松开取消";

    snprintf(buf, sizeof(buf), "长按中 %d%% · %s", LP.pct, verb);
    if (s_legend != NULL) {
        lv_label_set_text(s_legend, buf);
    }
}

static void lp_update_ui(void)
{
    if (LP.target == LP_ENTER) {
        if (LP.arc != NULL) {
            lv_arc_set_value(LP.arc, LP.pct);
        }
        if (UD.value != NULL) {
            char buf[8];

            snprintf(buf, sizeof(buf), "%d%%", LP.pct);
            lv_label_set_text(UD.value, buf);
        }
        return;
    }
    if (LP.bar != NULL) {
        lv_obj_set_width(LP.bar, LP.pct * 192 / 100);
    }
    lp_sync_text();
}

static void lp_cancel_done(lv_anim_t *a)
{
    (void)a;
    lp_ui_clear();
    if (s_screen == SCR_DIAL && UD.value != NULL) {
        dial_content(s_mode);
    }
    if (s_legend != NULL) {
        lv_label_set_text(s_legend, s_legend_base);
    }
}

static void lp_fade_exec(void *var, int32_t v)
{
    (void)var;
    if (LP.arc != NULL) {
        lv_arc_set_value(LP.arc, (int)v);
    }
    if (LP.track != NULL) {
        lv_obj_set_style_arc_opa(LP.track, (lv_opa_t)(255 * v / 100), 0);
    }
}

static void lp_cancel(void)
{
    /* ANIMATION #6：120ms ease-out 进度回到 0。 */
    lv_anim_t a;
    const int start = LP.pct;

    LP.active = false;
    if (LP.target == LP_ENTER && LP.arc != NULL) {
        lv_anim_init(&a);
        lv_anim_set_var(&a, LP.arc);
        lv_anim_set_values(&a, start, 0);
        lv_anim_set_duration(&a, 120);
        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
        lv_anim_set_exec_cb(&a, lp_fade_exec);
        lv_anim_set_ready_cb(&a, lp_cancel_done);
        lv_anim_start(&a);
    } else {
        lp_cancel_done(NULL);
    }
}

static void lp_start_ui(void)
{
    if (LP.target == LP_ENTER) {
        LP.track = RING(s_scr, UD.cx, UD.cy, UD.d, 4, P_TRACK);
        LP.arc = ARC(s_scr, UD.cx, UD.cy, UD.d, 4, 135, 270,
                     C_DEEP[M_RIDE], true, LV_OPA_COVER);
        lv_arc_set_value(LP.arc, 0);
        if (UD.desc != NULL) {
            lv_label_set_text(UD.desc, "长按进入");
        }
        if (UD.value != NULL) {
            lv_label_set_text(UD.value, "0%");
        }
        if (UD.unit != NULL) {
            lv_obj_add_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
        }
        if (UD.sub != NULL) {
            lv_label_set_text(UD.sub, "松手取消");
        }
        lp_sync_text();
    } else {
        const int y = (s_screen == SCR_DIAL) ? 288 : 292;

        LP.bar = B(s_scr, 24, y, 0, 2, C_DEEP[M_RIDE], LV_OPA_COVER, 1);
        lp_sync_text();
    }
}

static void do_short(int key);

static void lp_fire(void)
{
    lp_target_t target = LP.target;

    LP.active = false;
    lp_ui_clear();
    switch (target) {
        case LP_ENTER:
            if (UD.unit != NULL) {
                lv_obj_remove_flag(UD.unit, LV_OBJ_FLAG_HIDDEN);
            }
            enter_selected_mode();
            break;
        case LP_ACTIVATE:
            settings_activate();
            break;
        case LP_ADJUST:
            display_adjust();
            break;
        case LP_SEARCH:
            sensor_search();
            break;
        case LP_TOGGLE_RIDE:
            toggle_ride();
            if (s_screen == SCR_DIAL || s_screen == SCR_RIDE) {
                rebuild();
            }
            break;
        default:
            break;
    }
}

static void lp_tick(void)
{
    uint32_t dt;

    if (!LP.active) {
        return;
    }
    dt = lv_tick_get() - LP.t0;
    {
        int p = dt >= 800 ? 100 : (int)(dt * 100 / 800);

        if (p != LP.pct) {
            LP.pct = p;
            lp_update_ui();
        }
        if (p >= 100) {
            lp_fire();
        }
    }
}

static void lp_begin(int key)
{
    LP.active = true;
    LP.key = key;
    LP.t0 = lv_tick_get();
    LP.pct = 0;
    if (key == 2) {
        LP.target = LP_TOGGLE_RIDE;
    } else if (s_screen == SCR_DIAL) {
        LP.target = LP_ENTER;
    } else if (s_screen == SCR_SETTINGS) {
        LP.target = LP_ACTIVATE;
    } else if (s_screen == SCR_DISPLAY) {
        LP.target = LP_ADJUST;
    } else {
        LP.target = LP_SEARCH;
    }
    lp_start_ui();
    lp_update_ui();
}

