static void do_short(int key)
{
    if (key == 1) {
        switch (s_screen) {
            case SCR_DIAL: dial_rotate_next(); break;
            case SCR_RIDE:
                s_ride_page = (s_ride_page + 1) % 3;
                ride_page_types();
                ride_refresh();
                break;
            case SCR_NAV:
                toast("导航：北向上 / 车头向上");
                break;
            case SCR_RECORD:
                if (s_rec_sel + 1 < (s_rec_n < 4 ? s_rec_n : 4)) {
                    s_rec_sel++;
                    rec_sel_move(true);
                    rec_rows();
                }
                break;
            case SCR_SETTINGS:
                s_set_sel = (s_set_sel + 1) % 4;
                set_focus_apply(true);
                break;
            case SCR_DISPLAY:
                s_disp_sel = (s_disp_sel + 1) % 4;
                disp_focus_apply(true);
                break;
            case SCR_SENSOR:
                s_sens_sel = (s_sens_sel + 1) % 3;
                sens_focus_apply(true);
                sens_values();
                break;
            case SCR_ABOUT:
                s_about_sel = (s_about_sel + 1) % 4;
                about_focus_apply();
                break;
            default:
                break;
        }
    } else {
        go_back();
    }
}

static void ui_tick(lv_timer_t *t)
{
    (void)t;
    for (;;) {
        int key = 0;
        bool down = false;

        if (!sim_display_take_key_event(&key, &down)) {
            break;
        }
        if (s_busy) {
            continue;
        }
        if (down) {
            if (LP.active) {
                continue;
            }
            if ((key == 1 && screen_has_lp1()) ||
                (key == 2 && screen_has_lp2())) {
                lp_begin(key);
            } else {
                do_short(key);
            }
        } else {
            if (LP.active && LP.key == key) {
                const uint32_t held = lv_tick_get() - LP.t0;

                if (held < 160) {
                    LP.active = false;
                    lp_ui_clear();
                    if (s_screen == SCR_DIAL) {
                        dial_content(s_mode);
                    }
                    if (s_legend != NULL) {
                        lv_label_set_text(s_legend, s_legend_base);
                    }
                    do_short(key);
                } else {
                    lp_cancel();
                }
            }
        }
    }
    lp_tick();
    if (s_toast_until != 0 && lv_tick_get() > s_toast_until) {
        s_toast_until = 0;
        if (s_legend != NULL) {
            lv_label_set_text(s_legend, s_legend_base);
        }
    }
    tour_tick();
}

