static int32_t s_tr_p;
static lv_anim_t *s_tr_anim;
static int s_tr_cy0, s_tr_cy1, s_tr_d0, s_tr_d1;
static scr_t s_tr_next;

static void tr_exec(void *var, int32_t p)
{
    (void)var;
    {
        const int cy = s_tr_cy0 + (s_tr_cy1 - s_tr_cy0) * (int)p / 1000;
        const int d = s_tr_d0 + (s_tr_d1 - s_tr_d0) * (int)p / 1000;

        dial_geometry(120, cy, d, 255 * (1000 - (int)p) / 1000);
    }
}

static void tr_done(lv_anim_t *a)
{
    (void)a;
    s_tr_anim = NULL;
    s_busy = false;
    s_screen = s_tr_next;
    rebuild();
}

static void dial_out_anim(int cy1, int d1, scr_t next)
{
    lv_anim_t a;

    s_busy = true;
    s_tr_cy0 = UD.cy;
    s_tr_cy1 = cy1;
    s_tr_d0 = UD.d;
    s_tr_d1 = d1;
    s_tr_next = next;
    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_tr_p);
    lv_anim_set_values(&a, 0, 1000);
    lv_anim_set_duration(&a, 80); /* #3 阶段 A：0–80ms 环收缩 */
    lv_anim_set_path_cb(&a, lv_anim_path_ease_in_out);
    lv_anim_set_exec_cb(&a, tr_exec);
    lv_anim_set_ready_cb(&a, tr_done);
    s_tr_anim = lv_anim_start(&a);
}

static int32_t s_in_p;

static void dial_in_exec(void *var, int32_t p)
{
    (void)var;
    {
        const int cy = s_tr_cy0 + (s_tr_cy1 - s_tr_cy0) * (int)p / 1000;
        const int d = s_tr_d0 + (s_tr_d1 - s_tr_d0) * (int)p / 1000;

        dial_geometry(120, cy, d, 255 * (int)p / 1000);
    }
}

static void dial_in_ready(lv_anim_t *a)
{
    (void)a;
    s_busy = false;
}

static void dial_in(int cy0, int d0, int dur)
{
    lv_anim_t a;

    s_busy = true;
    s_tr_cy0 = cy0;
    s_tr_cy1 = 146;
    s_tr_d0 = d0;
    s_tr_d1 = 160;
    dial_geometry(120, cy0, d0, 0);
    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_in_p);
    lv_anim_set_values(&a, 0, 1000);
    lv_anim_set_duration(&a, dur);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
    lv_anim_set_exec_cb(&a, dial_in_exec);
    lv_anim_set_ready_cb(&a, dial_in_ready);
    lv_anim_start(&a);
}

static void enter_selected_mode(void)
{
    int mode = s_mode;

    if (s_rot_anim != NULL) {
        lv_anim_delete(&s_rot_p, NULL);
        s_rot_anim = NULL;
        if (UD.fill != NULL) {
            lv_obj_delete(UD.fill);
            lv_obj_delete(UD.trk);
        }
        UD.fill = UD.fill2;
        UD.trk = UD.trk2;
        UD.fill2 = NULL;
        UD.trk2 = NULL;
        SET_ARC_OPA(UD.fill, 255);
        SET_ARC_OPA(UD.trk, 255);
        mode = s_rot_to_mode;
        s_mode = mode;
        s_angle = s_rot_a1;
        UD.angle = s_angle;
        dial_pointer_layout(s_angle);
        dial_content(mode);
    }
    if (mode == M_RIDE) {
        dial_out_anim(106, 152, SCR_RIDE);
    } else {
        dial_out_anim(146, 120, mode_screen(mode));
    }
}

static void settings_to_sub(scr_t sub)
{
    if (US.titlebar != NULL) {
        lv_obj_set_width(US.titlebar, 0);
        {
            lv_anim_t a;

            lv_anim_init(&a);
            lv_anim_set_var(&a, US.titlebar);
            lv_anim_set_values(&a, 0, 20);
            lv_anim_set_duration(&a, 100);
            lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
            lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_width);
            lv_anim_start(&a);
        }
    }
    s_busy = true;
    s_tr_next = sub;
    {
        lv_anim_t a;

        lv_anim_init(&a);
        lv_anim_set_var(&a, &s_tr_p);
        lv_anim_set_values(&a, 0, 1000);
        lv_anim_set_duration(&a, 100);
        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
        lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)NULL);
        lv_anim_set_ready_cb(&a, tr_done);
        /* 用 0 宽的 exec 无法挂空函数，这里用 dial 的 p 变量做计时。 */
        lv_anim_set_exec_cb(&a, tr_exec);
        s_tr_cy0 = 146;
        s_tr_cy1 = 146;
        s_tr_d0 = 160;
        s_tr_d1 = 160;
        s_tr_anim = lv_anim_start(&a);
    }
}

static void settings_activate(void)
{
    switch (s_set_sel) {
        case 0:
            settings_to_sub(SCR_DISPLAY);
            break;
        case 1:
            settings_to_sub(SCR_SENSOR);
            break;
        case 2:
            s_sound = !s_sound;
            lv_label_set_text(US.val[2], s_sound ? "开" : "关");
            toast(s_sound ? "声音已开启" : "声音已关闭");
            break;
        default:
            settings_to_sub(SCR_ABOUT);
            break;
    }
}

static void display_adjust(void)
{
    switch (s_disp_sel) {
        case 0:
            s_bright += 10;
            if (s_bright > 100) s_bright = 10;
            disp_values();
            toast("亮度已调节");
            break;
        case 1:
            s_dark = !s_dark;
            disp_values();
            toast(s_dark ? "主题：深" : "主题：浅");
            break;
        case 2:
            s_lock = (s_lock == 15) ? 30 : (s_lock == 30) ? 60
                     : (s_lock == 60) ? 0 : 15;
            disp_values();
            toast("自动锁定已调整");
            break;
        default:
            s_sun = !s_sun;
            disp_values();
            toast(s_sun ? "阳光下增强：开" : "阳光下增强：关");
            break;
    }
}

static void sensor_search(void)
{
    s_sens_search = s_sens_sel;
    s_sens_ticks = 0;
    s_sens_bars[s_sens_sel] = 0;
    sens_values();
    toast("正在搜索…");
}

static void sensor_tick(void)
{
    if (s_sens_search < 0) {
        return;
    }
    s_sens_ticks++;
    s_sens_blink = ((s_sens_ticks / 1) % 2) == 0;
    if (s_sens_ticks >= 3) {
        const int i = s_sens_search;

        s_sens_search = -1;
        s_sens_on[i] = true;
        s_sens_bars[i] = 4;
        if (i == 2) {
            snprintf(s_sens_dev[2], sizeof(s_sens_dev[2]), "Magene S3+");
        }
        toast("已连接");
    }
    if (s_screen == SCR_SENSOR) {
        sens_values();
    }
}

static void go_back(void)
{
    switch (s_screen) {
        case SCR_DISPLAY:
        case SCR_SENSOR:
        case SCR_ABOUT:
            s_busy = true;
            s_tr_next = SCR_SETTINGS;
            {
                lv_obj_t *bar = (s_screen == SCR_DISPLAY) ? UP.titlebar
                                : (s_screen == SCR_SENSOR) ? UX.titlebar
                                                           : UA.titlebar;

                if (bar != NULL) {
                    lv_obj_set_width(bar, 20);
                    {
                        lv_anim_t a;

                        lv_anim_init(&a);
                        lv_anim_set_var(&a, bar);
                        lv_anim_set_values(&a, 20, 0);
                        lv_anim_set_duration(&a, 100);
                        lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                        lv_anim_set_exec_cb(&a,
                                            (lv_anim_exec_xcb_t)lv_obj_set_width);
                        lv_anim_start(&a);
                    }
                }
            }
            {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, &s_tr_p);
                lv_anim_set_values(&a, 0, 1000);
                lv_anim_set_duration(&a, 100);
                lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                lv_anim_set_exec_cb(&a, tr_exec);
                lv_anim_set_ready_cb(&a, tr_done);
                s_tr_cy0 = 146;
                s_tr_cy1 = 146;
                s_tr_d0 = 160;
                s_tr_d1 = 160;
                s_tr_anim = lv_anim_start(&a);
            }
            break;

        case SCR_RIDE: {
            /* ANIMATION #4：hero 60ms 退出 → 硬切 → 环展开 120ms。 */
            lv_obj_t *hero = (UR.hero != NULL) ? lv_obj_get_parent(UR.hero)
                                               : NULL;

            s_busy = true;
            if (hero != NULL) {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, hero);
                lv_anim_set_values(&a, 255, 0);
                lv_anim_set_duration(&a, 60);
                lv_anim_set_exec_cb(&a, (lv_anim_exec_xcb_t)lv_obj_set_style_opa);
                lv_anim_start(&a);
            }
            s_tr_next = SCR_DIAL;
            {
                lv_anim_t a;

                lv_anim_init(&a);
                lv_anim_set_var(&a, &s_tr_p);
                lv_anim_set_values(&a, 0, 1000);
                lv_anim_set_duration(&a, 60);
                lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
                lv_anim_set_exec_cb(&a, tr_exec);
                lv_anim_set_ready_cb(&a, tr_done);
                s_tr_cy0 = 146;
                s_tr_cy1 = 146;
                s_tr_d0 = 160;
                s_tr_d1 = 160;
                s_tr_anim = lv_anim_start(&a);
            }
            break;
        }

        case SCR_NAV:
        case SCR_RECORD:
            s_screen = SCR_DIAL;
            rebuild();
            dial_in(120, 120, 160);
            break;

        case SCR_SETTINGS:
            s_screen = SCR_DIAL;
            rebuild();
            dial_in(120, 120, 160);
            break;

        default:
            break;
    }
}

/* `lv_anim_exec_xcb_t` 对 lv_obj_set_style_opa 的签名不一致（多一个 selector），
 * 上面的 set_style_opa 不能直接当 exec 用，编译期会在这里报出来；
 * 下面给一个真正的包装。 */
static void hero_opa_exec(void *obj, int32_t v)
{
    lv_obj_set_style_opa((lv_obj_t *)obj, (lv_opa_t)v, 0);
}

