static void rebuild(void)
{
    lv_obj_t *old = s_scr;

    nav_stop();
    memset(&UD, 0, sizeof(UD));
    memset(&UR, 0, sizeof(UR));
    memset(&UN, 0, sizeof(UN));
    memset(&UC, 0, sizeof(UC));
    memset(&US, 0, sizeof(US));
    memset(&UP, 0, sizeof(UP));
    memset(&UX, 0, sizeof(UX));
    memset(&UA, 0, sizeof(UA));
    s_legend = NULL;
    s_rot_anim = NULL;
    LP.active = false;
    lv_obj_clean(old);

    switch (s_screen) {
        case SCR_RIDE: ride_build(); break;
        case SCR_NAV: nav_build(); break;
        case SCR_RECORD: rec_build(); break;
        case SCR_SETTINGS: set_build(); break;
        case SCR_DISPLAY: disp_build(); break;
        case SCR_SENSOR: sens_build(); break;
        case SCR_ABOUT: about_build(); break;
        case SCR_ICONS: icons_build(false); break;
        case SCR_ICONS_DEMO: icons_build(true);
            break;
        default: dial_build(); break;
    }
    printf("helm: screen=%s mode=%d ride=%d\n", SCR_NAME[s_screen], s_mode,
           R.active ? 1 : 0);
    fflush(stdout);
}

static void data_tick(lv_timer_t *t)
{
    (void)t;
    s_clock_tick++;
    if (s_clock_tick % 60 == 0) {
        s_min = (s_min + 1) % (24 * 60);
        if (s_screen == SCR_DIAL) {
            dial_status_refresh();
        }
    }
    if (s_clock_tick % 120 == 0 && s_batt > 5) {
        s_batt--;
        if (s_screen == SCR_DIAL) {
            dial_status_refresh();
        }
    }
    if (s_sens_search >= 0) {
        sensor_tick();
    }
    if (R.active) {
        R.elapsed_s++;
        ride_step();
        if (s_screen == SCR_RIDE) {
            ride_refresh();
        } else if (s_screen == SCR_NAV) {
            nav_refresh();
#ifdef SIM_WITH_UI
            if (s_nav_view != NULL) {
                vmap_view_set_center(s_nav_view,
                                     s_nav_lon + R.dist_km * 0.00004,
                                     s_nav_lat);
            }
            {
                char buf[24];

                snprintf(buf, sizeof(buf), "%d m", 300);
                (void)buf;
            }
#endif
        } else if (s_screen == SCR_DIAL) {
            dial_content(s_mode);
        }
    }
}

