static scr_t screen_from_env(void)
{
    const char *s = getenv("SIM_HELM_SCREEN");

    if (s == NULL || s[0] == '\0' || strcmp(s, "main") == 0) {
        return SCR_DIAL;
    }
    if (strcmp(s, "rotate") == 0 || strcmp(s, "longpress") == 0) {
        return SCR_DIAL;
    }
    for (int i = 0; i < SCR_COUNT; i++) {
        if (strcmp(s, SCR_NAME[i]) == 0) {
            return (scr_t)i;
        }
    }
    fprintf(stderr, "sim: unknown SIM_HELM_SCREEN=%s (main|ride|nav|record|"
                    "settings|display|sensor|about|icons|icons-demo)\n", s);
    return SCR_DIAL;
}

void scene_helm_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    s_scr = scr;
    s_screen = SCR_DIAL;
    rec_init();
    s_batt = 86;
    s_min = 14 * 60 + 32;
    s_clock_tick = 0;

    {
        const char *dir = getenv("SIM_HELM_TOUR");

        if (dir != NULL && dir[0] != '\0') {
            snprintf(s_tour_dir, sizeof(s_tour_dir), "%s", dir);
            (void)mkdir(s_tour_dir, 0755);
            s_tour_on = true;
            s_tour_frame = 0;
            s_tour_idx = 0;
            if (screen_from_env() != SCR_DIAL) {
                fprintf(stderr, "sim: SIM_HELM_TOUR ignores SIM_HELM_SCREEN\n");
            }
            printf("helm-tour: dir=%s\n", s_tour_dir);
        } else {
            s_screen = screen_from_env();
            {
                const char *sel = getenv("SIM_HELM_SEL");

                if (sel != NULL) {
                    s_set_sel = atoi(sel) % 4;
                    s_disp_sel = atoi(sel) % 4;
                    s_sens_sel = atoi(sel) % 3;
                    s_about_sel = atoi(sel) % 4;
                }
            }
        }
    }

    if (s_screen == SCR_DIAL) {
        dial_build();
        printf("helm: screen=main mode=%d\n", s_mode);
    } else {
        rebuild();
    }

    s_ui_timer = lv_timer_create(ui_tick, 16, NULL);
    s_data_timer = lv_timer_create(data_tick, 1000, NULL);
    (void)s_ui_timer;
    (void)s_data_timer;
}
