static void lp_tick(void)
{
    uint32_t dt;

    if (!LP.active) {
        return;
    }
    dt = lv_tick_get() - LP.t0;
    {
        int p = dt >= 800 ? 100 : (int)(dt * 100 / 800);

        if (p != LP.pct) {
            LP.pct = p;
            lp_update_ui();
        }
        if (p >= 100) {
            lp_fire();
        }
    }
}

