#include <X11/Xlib.h>
#include <X11/keysym.h>
#include <X11/extensions/XTest.h>
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main(int argc, char **argv)
{
    if (argc < 4) {
        fprintf(stderr, "usage: %s <winid> <key> <hold_ms> [wait_before_ms]\n", argv[0]);
        return 2;
    }
    Display *d = XOpenDisplay(NULL);
    if (!d) return 1;
    Window w = (Window)strtoul(argv[1], NULL, 0);
    XSetInputFocus(d, w, RevertToParent, CurrentTime);
    XFlush(d);
    usleep(atoi(argv[4] ? argv[4] : "0") * 1000);
    KeySym ks = XStringToKeysym(argv[2]);
    KeyCode kc = XKeysymToKeycode(d, ks);
    XTestFakeKeyEvent(d, kc, True, CurrentTime);
    XFlush(d);
    usleep(atoi(argv[3]) * 1000);
    XTestFakeKeyEvent(d, kc, False, CurrentTime);
    XFlush(d);
    XCloseDisplay(d);
    return 0;
}
